# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HUCURÂT SURESİ 10-11. AYETLER: KARDEŞLİK VE TOPLUMSAL SAYGI</text>\n  <rect x="25" y="48" width="650" height="72" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="16" font-weight="bold" fill="#1d4ed8">﴿ إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا بَيْنَ أَخَوَيْكُمْ ﴾ (Hucurât, 10)</text>\n  <text x="350" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">"Müminler ancak kardeştirler. Öyleyse kardeşlerinizin arasını düzeltin (ıslah edin)..."</text>\n  <rect x="25" y="134" width="205" height="106" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="127" y="158" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">1. Alay Etmeme (İstihza)</text>\n  <text x="38" y="182" font-size="11" fill="#334155">Hiçbir topluluk diğer bir</text>\n  <text x="38" y="198" font-size="11" fill="#334155">toplulukla alay etmesin;</text>\n  <text x="38" y="214" font-size="11" fill="#334155">belki onlar kendilerinden</text>\n  <text x="38" y="230" font-size="11" font-weight="bold" fill="#14532d">daha hayırlıdır.</text>\n  <rect x="247" y="134" width="205" height="106" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="158" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">2. Ayıplamama (Lemz)</text>\n  <text x="260" y="182" font-size="11" fill="#334155">Müminler kendi nefislerini</text>\n  <text x="260" y="198" font-size="11" fill="#334155">ve din kardeşlerini</text>\n  <text x="260" y="214" font-size="11" fill="#334155">küçük düşürüp</text>\n  <text x="260" y="230" font-size="11" font-weight="bold" fill="#854d0e">ayıplamamalıdır.</text>\n  <rect x="470" y="134" width="205" height="106" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="572" y="158" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">3. Kötü Lakap Takmama</text>\n  <text x="483" y="182" font-size="11" fill="#334155">İnsanları hoşlanmadıkları</text>\n  <text x="483" y="198" font-size="11" fill="#334155">kötü lakaplarla çağırmak</text>\n  <text x="483" y="214" font-size="11" fill="#334155">(tenâbüz bi\'l-elkâb)</text>\n  <text x="483" y="230" font-size="11" font-weight="bold" fill="#9d174d">yasaklanmıştır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HUCURÂT SURESİ 12-13. AYETLER: ZAN, TECESSÜS, GIYBET VE TAKVA</text>\n  <rect x="20" y="48" width="210" height="120" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">1. Sû-i Zan (Kötü Zan)</text>\n  <text x="32" y="96" font-size="11" fill="#334155">Kesin bilgiye dayanmadan</text>\n  <text x="32" y="114" font-size="11" fill="#334155">insanlar hakkında kötü</text>\n  <text x="32" y="132" font-size="11" fill="#334155">tahminde bulunmaktır.</text>\n  <text x="32" y="152" font-size="11" font-weight="bold" fill="#991b1b">"Zannın bir kısmı günahtır."</text>\n  <rect x="245" y="48" width="210" height="120" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">2. Tecessüs (Kusur Arama)</text>\n  <text x="257" y="96" font-size="11" fill="#334155">İnsanların özel hayatını,</text>\n  <text x="257" y="114" font-size="11" fill="#334155">mahremiyetini ve gizli</text>\n  <text x="257" y="132" font-size="11" fill="#334155">kusurlarını araştırmaktır.</text>\n  <text x="257" y="152" font-size="11" font-weight="bold" fill="#854d0e">"Birbirinizin kusurunu aramayın."</text>\n  <rect x="470" y="48" width="210" height="120" rx="8" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">3. Gıybet (Çekiştirme)</text>\n  <text x="482" y="96" font-size="11" fill="#334155">Bir kimsenin arkasından</text>\n  <text x="482" y="114" font-size="11" fill="#334155">duyduğunda üzüleceği</text>\n  <text x="482" y="132" font-size="11" fill="#334155">şekilde konuşmaktır.</text>\n  <text x="482" y="152" font-size="10.5" font-weight="bold" fill="#581c87">(Ölmüş kardeş etini yemek gibidir)</text>\n  <rect x="20" y="180" width="660" height="62" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="204" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Hucurât Suresi 13. Ayet — Üstünlük Ölçüsü: TAKVA (إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ)</text>\n  <text x="350" y="226" text-anchor="middle" font-size="11.5" fill="#14532d">Soy, ırk, zenginlik veya makam değil; Allah katında en değerli olan, O\'na karşı sorumluluk bilinci (takvası) en yüksek olandır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BİRİNCİ BÖLÜM DEĞERLENDİRMESİ: KUR\'AN-I KERİM\'İ TANIYALIM</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Kur\'an\'ın İsim ve Sıfatları</text>\n  <text x="32" y="98" font-size="11" fill="#334155">• <tspan font-weight="bold">el-Furkân:</tspan> Hak ile batılı ayıran</text>\n  <text x="32" y="120" font-size="11" fill="#334155">• <tspan font-weight="bold">ez-Zikr:</tspan> Öğüt ve hatırlatma</text>\n  <text x="32" y="142" font-size="11" fill="#334155">• <tspan font-weight="bold">eş-Şifâ:</tspan> Kalplere şifa veren</text>\n  <text x="32" y="164" font-size="11" fill="#334155">• <tspan font-weight="bold">en-Nûr:</tspan> Yol aydınlatan ışık</text>\n  <text x="32" y="186" font-size="11" fill="#334155">• <tspan font-weight="bold">el-Hüdâ:</tspan> Doğru yola ileten</text>\n  <text x="32" y="208" font-size="11" fill="#334155">• <tspan font-weight="bold">el-Kitâb:</tspan> Yazılı ilahi kelam</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Kur\'an\'ın Ana Konuları</text>\n  <text x="257" y="98" font-size="11" fill="#334155">1. <tspan font-weight="bold">İnanç (İman):</tspan> Tevhid, ahiret</text>\n  <text x="257" y="122" font-size="11" fill="#334155">2. <tspan font-weight="bold">İbadet:</tspan> Namaz, oruç, zekât</text>\n  <text x="257" y="146" font-size="11" fill="#334155">3. <tspan font-weight="bold">Ahlak:</tspan> Doğruluk, adalet, edep</text>\n  <text x="257" y="170" font-size="11" fill="#334155">4. <tspan font-weight="bold">Muamelat:</tspan> Sosyal-hukuki hayat</text>\n  <text x="257" y="194" font-size="11" fill="#334155">5. <tspan font-weight="bold">Kıssalar:</tspan> Peygamberlerin ve</text>\n  <text x="268" y="212" font-size="11" fill="#334155">geçmiş kavimlerin ibretli tarihi</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Ayet ve Sure Mesajları</text>\n  <text x="482" y="100" font-size="11" font-weight="bold" fill="#854d0e">• Bakara 255 (Âyetü\'l-Kürsî):</text>\n  <text x="488" y="118" font-size="10.5" fill="#334155">Allah\'ın birliği (tevhid), el-Hayy</text>\n  <text x="488" y="134" font-size="10.5" fill="#334155">ve el-Kayyûm isimleri, kürsîsi.</text>\n  <text x="482" y="164" font-size="11" font-weight="bold" fill="#854d0e">• Hucurât Suresi (18 Ayet):</text>\n  <text x="488" y="182" font-size="10.5" fill="#334155">Medine dönemi; edep, haber</text>\n  <text x="488" y="198" font-size="10.5" fill="#334155">doğrulama, kardeşlik, gıybet</text>\n  <text x="488" y="214" font-size="10.5" fill="#334155">yasağı ve takva ölçüsü.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
